INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b62aa948-7fae-4053-9f1c-9981e18705c1', '21feff02-016d-46e2-bb9d-c27495133b1b', '21. óra: Gyakorlóóra: a tanult oszthatósági szabályok alkalmazása', 'Gyakorlás, igaz-hamis állítások, halmazábrák oszthatóságra.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "6f21a57a-93c6-472f-9310-7869e76f324d", "text": "Melyik szám osztható 2-vel, 3-mal és 5-tel is (azaz 30-cal)?", "type": "multiple-choice", "options": [{"id": "3440f341-363e-4639-929d-52254434ed57", "text": "90", "isCorrect": true}, {"id": "f675058a-a063-479e-a6b7-d4114ccb1674", "text": "45", "isCorrect": false}, {"id": "e20afea7-4aad-4714-8d8e-27469f7462b6", "text": "80", "isCorrect": false}, {"id": "251f7a8b-eb8b-4785-b814-08f37dec0237", "text": "100", "isCorrect": false}], "timeLimit": 15}, {"id": "ca1a4d0d-4afb-438e-aa12-159104e010cc", "text": "A 180 osztható 4-gyel és 9-cel is.", "type": "true-false", "options": [{"id": "07f565f9-3b8c-43d8-8430-028243fe2d4e", "text": "Igaz", "isCorrect": true}, {"id": "f04b96bf-5236-4856-a90a-01f9cba404da", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9a19a733-fa6d-4bd2-a144-bdd2fbbc6b0c", "text": "Hány olyan szám van 1 és 100 között, ami osztható 10-zel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0ee81814-4ba5-47ed-8894-b2c7e52a841d", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "237a1193-4526-4cde-a882-e63e99a169bb", "text": "729 (7+2+9=18)", "isCorrect": true}, {"id": "68448d77-8361-4351-be32-44b6dd816b32", "text": "721", "isCorrect": false}, {"id": "7c759861-c1f6-46f1-9cdc-a109c7c654db", "text": "725", "isCorrect": false}, {"id": "487f6f82-5979-4e8f-ba7a-2cc60a85e9e0", "text": "730", "isCorrect": false}], "timeLimit": 15}, {"id": "352d986e-9d42-424b-b7f3-7d8c12003a07", "text": "Ha egy szám osztható 10-zel, akkor 5-tel is osztható.", "type": "true-false", "options": [{"id": "6ae68ced-4c57-4b52-aefc-3c2f4a3fb684", "text": "Igaz", "isCorrect": true}, {"id": "41ce7cbc-635f-4fdd-ab5e-7f69ae7e013d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b9cd180d-92f4-492c-b494-cefd54dad645", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 5-tel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e413ff06-945d-475a-8ada-36d143e0d79f", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 3-mal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "102"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9e33b830-3f18-47a7-91f1-c894fc3ecc7e', '21feff02-016d-46e2-bb9d-c27495133b1b', '22. óra: Többszörös, közös többszörös', 'Közös többszörösök, legkisebb közös többszörös (lkkt) és közös nevező.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "dc6bbc65-ca15-436e-88eb-4ca1cb7796fb", "text": "Mit jelent két szám legkisebb közös többszöröse (lkkt)?", "type": "multiple-choice", "options": [{"id": "4afa0260-b191-4de7-bc59-771217732f39", "text": "A legkisebb olyan pozitív számot, amely mindkét számmal osztható", "isCorrect": true}, {"id": "43dd4e22-1547-453b-a064-5e3a69fcc1f7", "text": "A két szám szorzatát mindig", "isCorrect": false}, {"id": "0e8dcdaf-a555-4c31-9476-4c285ae37d69", "text": "A legkisebb osztót", "isCorrect": false}, {"id": "dc74d2a0-0c88-4d76-b813-02e5cf4393a1", "text": "A két szám különbségét", "isCorrect": false}], "timeLimit": 15}, {"id": "31023e3f-656a-4f2d-9475-eb06872f349a", "text": "Mennyi a 4 és 6 legkisebb közös többszöröse, lkkt(4, 6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "2d4c8fc7-b3e2-4352-8b96-81d18a1c8f09", "text": "Mennyi a 3 és 5 legkisebb közös többszöröse, lkkt(3, 5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "9b295920-1239-4c72-8e27-b65f2915a015", "text": "Relatív prímek (pl. 3 és 5) legkisebb közös többszöröse a két szám szorzata.", "type": "true-false", "options": [{"id": "e7657314-9f9b-4d42-b3d4-5789dfd0cf97", "text": "Igaz", "isCorrect": true}, {"id": "57c2852b-3d3d-4f49-a752-bea27ad1232f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "79f79bf2-b461-451b-ad07-b5415280c686", "text": "A közös többszöröst használjuk törtek közös nevezőre hozásakor.", "type": "true-false", "options": [{"id": "920cefed-691e-4128-8a0b-271ce6eff4b6", "text": "Igaz", "isCorrect": true}, {"id": "b88f774f-0a82-498e-8bcf-372422920463", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fc3217d6-c9b2-49c2-ab8b-8096deb07035", "text": "Mennyi a 6 és 8 legkisebb közös többszöröse?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "834d961b-a54b-48a3-af3f-c77e30e91f12", "text": "Melyik szám közös többszöröse a 2-nek és a 5-nek?", "type": "multiple-choice", "options": [{"id": "63005a99-f5fe-4aca-91aa-8a367a3bcbe1", "text": "10", "isCorrect": true}, {"id": "6b3f4b87-0d22-429b-939e-0718b755d5f1", "text": "15", "isCorrect": false}, {"id": "c6f00fba-1863-45af-9a03-3f31738b9a6a", "text": "8", "isCorrect": false}, {"id": "3059b575-51ed-4bd4-9007-2d9a9559d0a0", "text": "12", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('728fba05-8844-4bf9-82f2-576277b122c1', '21feff02-016d-46e2-bb9d-c27495133b1b', '23. óra: Osztó, közös osztó', 'Közös osztók, legnagyobb közös osztó (lnko) és törtek egyszerűsítése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "6351bcda-a8bb-425d-8f16-a80764f82365", "text": "Mit jelent két szám legnagyobb közös osztója (lnko)?", "type": "multiple-choice", "options": [{"id": "b8105a91-d805-40cd-a8a5-1427402bf310", "text": "A legnagyobb olyan pozitív számot, amely mindkét számot osztja", "isCorrect": true}, {"id": "8e127961-415a-43c4-a657-6f3ca208f24f", "text": "A két szám összege", "isCorrect": false}, {"id": "1cf44ecb-7d63-4aad-ac36-404f697370c3", "text": "A legkisebb többszöröst", "isCorrect": false}, {"id": "775d3e58-e997-4358-8cfe-670d4a4e431d", "text": "Az 1-et mindig", "isCorrect": false}], "timeLimit": 15}, {"id": "136f428d-cd70-44e3-b99c-c075f7640722", "text": "Mennyi a 12 és 18 legnagyobb közös osztója, lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "696ad854-6686-46ad-af0f-d1491fdf096e", "text": "Mennyi a 15 és 25 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "42071551-0fa6-45d1-8f54-52fcd8aa023b", "text": "Két számot relatív prímeknek nevezünk, ha a legnagyobb közös osztójuk 1.", "type": "true-false", "options": [{"id": "d874495d-d55b-488d-a1b2-d6c1df37a8ea", "text": "Igaz", "isCorrect": true}, {"id": "045d582c-1d71-4f97-bd11-9a46b7b20af6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "38bd5a8d-f6bf-4bf8-ac1d-560033c6f4d8", "text": "A 8 és 9 relatív prímek (lnko(8,9) = 1).", "type": "true-false", "options": [{"id": "7ec9e8a1-4962-4754-ac59-ffdfa2d6e411", "text": "Igaz", "isCorrect": true}, {"id": "95011659-083e-4ffb-a2a6-c2e517526955", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "48537c53-9efb-4c08-ab72-95f5cdc9e572", "text": "A legnagyobb közös osztóval egyszerűsítve a törtet a legegyszerűbb alakot kapjuk.", "type": "true-false", "options": [{"id": "13fca44c-ecd3-427d-8448-0a619c00e6ea", "text": "Igaz", "isCorrect": true}, {"id": "8e32a657-d0e4-46f4-9efb-5cb8a1c99057", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d3698762-5430-4890-96f5-5e956e5be926", "text": "Mennyi a 20 és 30 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8b25052a-2ca5-445e-a8ac-c20f8e79a7b2', '21feff02-016d-46e2-bb9d-c27495133b1b', '24. óra: Összefoglalás', 'A tanult fogalmak ismétlése, rendszerezése az egész számok és oszthatóság témakörből.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "a9a29a5c-dafb-490a-8170-1d5b02d7211c", "text": "Mennyi (-12) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b48d0a8e-fe66-48d2-9d26-dc88278c54e2", "text": "Mennyi lkkt(6, 9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "3aa2f14a-294a-4cc1-9b90-41f030f6c387", "text": "Mennyi lnko(24, 36)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "00c11c5a-3664-41c6-b762-8ed7007b5760", "text": "A 135 osztható 5-tel és 9-cel is.", "type": "true-false", "options": [{"id": "6fae608f-b0c1-45c8-a21e-6a3a2cc7402c", "text": "Igaz", "isCorrect": true}, {"id": "2305ae96-423d-4b5d-8c97-06ecc3ab2e11", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "69350484-aa06-42f9-88ff-74fc2188a0e7", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "61b6bccc-edb7-430b-8828-c733a0b0fdb2", "text": "Igaz", "isCorrect": true}, {"id": "32c5e95c-2797-466c-82b0-cdb500b0f745", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b2ebfeaf-61bf-442f-b739-a9925df66f73", "text": "Mennyi (-50) : (+10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "6201e365-740e-476b-85e4-bb4ce8530ce7", "text": "Melyik szám osztható 4-gyel?", "type": "multiple-choice", "options": [{"id": "9b8d4b3a-25c6-404b-92d4-6393a4e24282", "text": "524", "isCorrect": true}, {"id": "addf1a2c-03a5-4ed2-a184-5ab933a7ef57", "text": "522", "isCorrect": false}, {"id": "0d1e3bb6-a1a9-475b-b680-0096faac6afa", "text": "521", "isCorrec