INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('abd1f236-2eeb-44e1-87a5-f510ed6c4a40', '21feff02-016d-46e2-bb9d-c27495133b1b', '25. óra: Tesztfeladatok megoldása', 'Feladatmegoldási gyakorlat önállóan az oszthatósági téma lezárása előtt.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "715a7e2d-7cfb-4e09-a8a4-6fcc385154ea", "text": "Hány osztója van a 10-nek? (1, 2, 5, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "648573e1-01ce-42f3-b7ef-97a836417bb0", "text": "Osztható-e a 432 6-tal?", "type": "true-false", "options": [{"id": "0d76eb1f-4212-4284-b962-80fae905e3ed", "text": "Igaz (páros és 4+3+2=9)", "isCorrect": true}, {"id": "78ebd6e3-90fc-4d3f-8fdf-602c46d48e03", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e0f19fe1-4f8b-49f5-808f-b7b3ead3b41c", "text": "Mennyi (-7) * (+6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-42"}, {"id": "66784198-ade3-4817-806a-52d63425a032", "text": "Melyik szorzat eredménye pozitív?", "type": "multiple-choice", "options": [{"id": "547fa2d2-e71c-4932-8077-aa8f61c34b08", "text": "(-4) * (-5)", "isCorrect": true}, {"id": "fd52e5b1-9d9e-4cca-8a88-809c8919da26", "text": "(-4) * (+5)", "isCorrect": false}, {"id": "08fc3f04-c688-41d8-8b48-3d841c54dfe3", "text": "(+4) * (-5)", "isCorrect": false}, {"id": "a981560f-da23-4b2a-93ad-68ed027d5bcc", "text": "(-4) * 0", "isCorrect": false}], "timeLimit": 15}, {"id": "859dc91d-f218-4cfb-a3b5-ffbc43d1c340", "text": "Mennyi a maradék, ha 47-et 5-tel osztunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "5b63edfc-62ac-4cbf-913b-ef4a0231f13d", "text": "A 17 prímszám.", "type": "true-false", "options": [{"id": "f6b4332d-3aca-4726-a763-86f5967cf872", "text": "Igaz", "isCorrect": true}, {"id": "62f65a9c-ca40-4021-95c9-00c8571212a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bfd7497e-862e-491c-94a6-b66b1d6ab6a0", "text": "Mennyi lkkt(4, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b42964ea-591e-4745-8ea6-8b9d1ab02ce6', '21feff02-016d-46e2-bb9d-c27495133b1b', '26. óra: Témazáró dolgozat', 'Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "a1cb76bb-c878-4d5c-816f-1f8576980cea", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "64f6c86d-58e1-4709-9303-83a2373149f2", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "f94b0038-2827-4e82-b8bd-76ea748a52ba", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "63194d87-1cef-4141-bcc9-b5af8fc82521", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "58ff851b-a3c0-499e-b554-320f231632a7", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "d19ee8ba-2228-4799-9640-0b57ec62469f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "958ce7a8-9cf8-49f4-baee-93db8758e9ef", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "e1313d81-28dd-45d1-aa70-9364b4ef69b9", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "34b4438a-3006-40c4-8d60-79086545c3d3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "70501abc-dc99-494b-b258-31b71739cdb1", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "d0960062-f73b-4b6f-934d-5d5a8e892fdb", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "01e1dbfc-1c55-4dbc-9028-d93c1c41e9a0", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "907c54fc-97d3-4ed9-9c43-e6c3ba10eb33", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "672b4cd8-c4bb-4f6a-8453-e5fa7f626c3e", "text": "10. Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "483c7100-e4af-4d46-9407-ec059d8a98a2", "text": "Igaz", "isCorrect": true}, {"id": "edf484f3-e60d-4868-b714-00577f873e78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0e5982cb-7158-420b-8c8a-6c54b8185339', '21feff02-016d-46e2-bb9d-c27495133b1b', '27. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "e1e9ad1b-304e-425a-bb9c-2034a7ab255f", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "4e4e85df-9857-4b90-8479-8733c69955f6", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "3adc2139-88c8-4776-b241-6b51fd0cfba2", "text": "A számok leírása", "isCorrect": false}, {"id": "01cb1b65-ecc5-41d5-867f-6b30ae1ab97d", "text": "A vonalzó használata", "isCorrect": false}, {"id": "b457c187-260b-4dfb-989f-2438d7ea585c", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "b04e97bc-8aca-4cb8-b0f3-21bcdd35d8d2", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "9579992a-e0c8-440b-934d-68f34d3373bc", "text": "Igaz", "isCorrect": true}, {"id": "399ec451-6f7e-436e-9f7e-e970b2561c99", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6cbf3510-3a3d-4255-9e82-decf25516a3b", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "85eedcf7-93b0-4403-bfda-d56c89aa7b93", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "ec5e429a-33e6-40da-90de-069753f1e28f", "text": "Igaz", "isCorrect": true}, {"id": "78f210c9-eae8-402b-9d27-17fb11dd0518", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "37ef3ec8-4690-405d-8745-0db9ed6b8c99", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "d031d8b2-28d4-4011-b687-98879f1d85b6", "text": "A dolgozatok áttekintése segít a hiányosságok pótlásában.", "type": "true-false", "options": [{"id": "80c1b104-39c7-4adb-9d82-6eb9a52707af", "text": "Igaz", "isCorrect": true}, {"id": "d564a77d-5aee-4197-9735-d3e85f4d76a6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "12fa6fb9-f82d-4157-accc-a514a3ba7873", "text": "Mennyi lnko(10, 15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('55f8e4f4-6bc3-4041-9e7c-afc7fe46160e', '21feff02-016d-46e2-bb9d-c27495133b1b', '28. óra: Mit tanultunk a törtekről? Ismétlés', 'Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b0d53e04-b69b-4d72-abd7-949fb8c80f60", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "ca099504-bbac-45d6-8e75-91cbff02d656", "text": "Számláló", "isCorrect": true}, {"id": "ac31afa7-9e31-4b78-9cbf-c41e68c0e56f", "text": "Nevező", "isCorrect": false}, {"id": "fdba3621-fc93-4c86-a891-0dad3cdde1e3", "text": "Törtvonal", "isCorrect": false}, {"id": "48939bbb-5670-4671-953d-fe53bcfc8367", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "e1d93959-6e04-4588-8716-65cae014f915", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "63095bf6-1ec5-4b64-9acf-3e9968155948", "text": "Nevező", "isCorrect": true}, {"id": "4d735cbf-d3c0-40e6-b4b4-cb07cadb2314", "text": "Számláló", "isCorrect": false}, {"id": "ffa37ae0-41e0-4f3b-8ade-f1498015f2da", "text": "Osztó", "isCorrect": false}, {"id": "81408374-09b1-4591-bbe9-225d07f24545", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "94d95d26-9d39-45cb-a068-405a84bccf62", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "f6da444a-68a7-4bf0-9fb5-b9c74c842c3d", "text": "6/8", "isCorrect": true}, {"id": "c7541b1e-8df1-403f-aa6b-a24e6a3bb697", "text": "5/6", "isCorrect": false}, {"id": "7c76553a-e7c6-4124-9a10-62c41845e377", "text": "3/8", "isCorrect": false}, {"id": "531d5883-2c6f-4e15-970f-3f4e07f85bd4", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "c4bd7bb6-13cf-49f1-9469-2d04e29266e6", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "0b33deb9-3908-43dc-a265-c6242c2b8b32", "text": "3/5", "isCorrect": true}, {"id": "799299c5-4747-4706-a7b0-bba2df5bc4a6", "text": "3/10", "isCorrect": false}, {"id": "57885d83-7d59-4721-9147-73b41177c6d3", "text": "6/5", "isCorrect": false}, {"id": "bdec7018-5f83-4a0e-bbee-1220008551aa", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "521bc8ec-b267-481f-b2d5-a9d34e90c7a4", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "70c2f35e-68f4-49f8-ad0c-7ee5740075b8", "text": "Igaz", "isCorrect": true}, {"id": "be9982c4-e4d0-45b9-acc1-01f63e9e6371", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "329e5554-1968-4e0d-9dcb-36b8eaa6410a", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "20553dff-b005-4178-b39d-51708a783f16", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "e4b0268b-feb5-4ba5-a198-659ee3a3ef2e", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "74ec0ed5-a6c9-466e-b744-583c37679469", "text": "2/6", "isCorrect": false}, {"id": "8a8a57d2-2460-4546-866d-01c452511f5b", "text": "2/4", "isCorrect": false}, {"id": "3365db5f-1928-4282-b285-293b3c190cb5", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a6b318a3-8e3e-4c6d-8696-0295633a4a56', '21feff02-016d-46e2-bb9d-c27495133b1b', '29. óra: Mit tanultunk a törtekről? Ismétlés II.', 'Összeadás és kivonás azonos és különböző nevezőjű törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "c07aac38-56e1-4e95-93b2-b18fdbed45e2", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "54935b2c-5fa9-4f4b-8a37-7b9d1ff2cb07", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "3c5957f2-4ea3-4f46-9bba-ecea472f02a8", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "0d2197ec-1c43-461b-9464-03b7331ebee0", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "7f2a9a9b-fc49-4787-a1d4-16a512c3a23c", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "38d162a0-3bf7-4395-a9fc-acc84b5a78f0", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "24eefafd-1443-4850-aa46-911d8474ea35", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "3660daef-dc63-4d0d-a15b-ea9e262f5f11", "text": "2/9", "isCorrect": false}, {"id": "d7043143-8c0b-4a85-99ea-986ad9e1ed41", "text": "1/9", "isCorrect": false}, {"id": "58e2216e-1862-4e1a-bf42-3a697d7ebbf1", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "646fc46d-406c-436d-b28c-56b31713a08c", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "e312114b-c211-4d20-b092-afeaa452e55c", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "bfc02f21-a82c-45d9-8824-27347a6fea3c", "text": "2/0", "isCorrect": false}, {"id": "6d73458b-b79c-4c59-86df-3eb45b67d9d8", "text": "8/8", "isCorrect": false}, {"id": "1e9dea8e-724d-4b68-a03f-6553dd596890", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "df9ed263-bcd8-4716-bb63-138d5d9bc48f", "text": "Az 1/2 és 2/4 egyenlő értékű törtek.", "type": "true-false", "options": [{"id": "736dfcbf-e178-48d7-8414-904d731cf38b", "text": "Igaz", "isCorrect": true}, {"id": "0fb792fb-6b5a-4469-9f38-e0c208a8f0b0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ec4b2efa-79df-46ad-a60b-4e97d0776e60", "text": "Hány nyolcad van 3/4-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "a1b810e5-c5c3-408a-97cc-83ccf257a21f", "text": "Mennyi 1 egészből kivonva 2/5-öt?", "type": "multiple-choice", "options": [{"id": "93a639c1-38ee-4f50-89ea-c2221d639fdc", "text": "3/5", "isCorrect": true}, {"id": "40d3ec51-27b2-483a-bc77-540cd8175296", "text": "1/5", "isCorrect": false}, {"id": "4f18b9a4-c961-420f-96d8-d16d36bc4a33", "text": "2/5", "isCorrect": false}, {"id": "5cdc32b7-722c-43e8-a141-673abee37c6f", "text": "5/5", "isCorrect": false}], "timeLimit": 15}, {"id": "98a25c28-4f99-4d40-86a5-dd7fef5db082", "text": "A törtvonal osztás műveletet jelent.", "type": "true-false", "options": [{"id": "a87f2801-8ec8-4b7b-9b79-c107da1e217a", "text": "Igaz", "isCorrect": true}, {"id": "65674f29-6ef2-4a17-9bd1-cc61dfd4fc6d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('33362b9d-4246-4175-9eed-53ec89086c29', '21feff02-016d-46e2-bb9d-c27495133b1b', '30. óra: Szorzás törttel, a reciprok', 'Tört szorzása törttel, reciprok fogalma.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "c527c5a4-76c2-4c27-a516-040b48293ba0", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "d601f548-e890-434b-b6a6-1af017444568", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "daa3c62c-2dd6-41e0-ada8-77197f85ff21", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "4f82937c-1574-43c2-8c76-561c02645149", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "24f9b70a-d47d-4e87-8ef9-89578ecfa134", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "a6827bee-07d7-49cf-9af4-4d480ee02102", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "388ea845-2dfc-4724-934a-c8b7502deea2", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "35ce9102-9740-4b11-a220-e4bc5b0e6ae7", "text": "5/8", "isCorrect": false}, {"id": "0de346f6-7c7e-48df-ae9b-063f77113dcd", "text": "6/8", "isCorrect": false}, {"id": "59805719-bdb2-43e8-bf22-844b76418644", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "82bef52a-2288-4ed7-a8ad-b4bcdb567617", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "d9681d74-3350-4adf-8ef5-b9d192216979", "text": "4/3", "isCorrect": true}, {"id": "44dded65-5b3e-412e-9afb-6c7e9415e9d3", "text": "-3/4", "isCorrect": false}, {"id": "d1cf83a5-9041-4436-8133-e642a2af4c47", "text": "1/4", "isCorrect": false}, {"id": "7e3db976-17b3-4bfa-a7d4-4abf206ca4be", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "0694c476-95f5-4180-9f6d-8cda92c9226e", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "df5025e6-ab72-41d9-a533-6180c7fd4df4", "text": "Igaz", "isCorrect": true}, {"id": "b4a0a303-d30e-46f5-85b6-4779690755f9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "71c3e0ec-95f6-45c5-80ef-087997230adb", "text": "Mi a 5 egész reciproka?", "type": "multiple-choice", "options": [{"id": "850e9556-f496-4d4d-a6c1-31d4e0193b7c", "text": "1/5", "isCorrect": true}, {"id": "5b6080bf-432d-4afa-9d22-c6d1ae463048", "text": "-5", "isCorrect": false}, {"id": "acebb456-91cb-498e-a33d-ceec7e807549", "text": "5/1", "isCorrect": false}, {"id": "ac8b37b9-7896-47d8-baac-517f80788e1f", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "f905db95-9459-4d3c-af09-18fcd065bc4d", "text": "A 0-nak nincs reciproka.", "type": "true-false", "options": [{"id": "35b79b4c-c797-46cb-9d7d-6f3c6a4047f1", "text": "Igaz", "isCorrect": true}, {"id": "801b5bfe-8399-4cf1-b1d5-219276ef7e8b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2c02edd-c883-4b60-9c64-39c6187e38ae", "text": "Mennyi 1/2 * 1/3?", "type": "multiple-choice", "options": [{"id": "48163c65-c355-4ac1-a6ea-0ce99c9922ab", "text": "1/6", "isCorrect": true}, {"id": "8efff8fb-28c7-4fbe-bd6a-4e4d9033afbd", "text": "2/5", "isCorrect": false}, {"id": "02f9070d-763c-4f15-853e-b43356af77af", "text": "1/5", "isCorrect": false}, {"id": "6b7fb6ed-8152-4945-8fe8-31c05ed4488d", "text": "2/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;